//! The Melodia course, built from the EarMaster course plan rather than from
//! hand-picked tags.
//!
//! `melodia_course.json` is generated by
//! `corpus/tools/build_melodia_app_course.py` from
//! `documents/melodia/course.json` and the installed library. It keeps the
//! source's module and lesson order and the exact piece ids of every lesson.
//! Two-part lessons list both parts as separate trials, because the sight-singing
//! exercise is monophonic.

use serde::Deserialize;
use serde_json::json;

use crate::courses::Course;
use crate::rp_courses::{lesson, module, workshop};

pub const MELODIA: &str = "melodia";

const PLAN: &str = include_str!("melodia_course.json");

#[derive(Deserialize)]
struct Data {
    modules: Vec<ModuleData>,
}

#[derive(Deserialize)]
struct ModuleData {
    title: String,
    lessons: Vec<LessonData>,
}

#[derive(Deserialize)]
struct LessonData {
    title: String,
    summary: String,
    ids: Vec<String>,
}

pub fn course() -> Course {
    let data: Data =
        serde_json::from_str(PLAN).expect("melodia_course.json is generated and valid");
    let modules = data
        .modules
        .into_iter()
        .filter_map(|m| {
            let lessons: Vec<_> = m
                .lessons
                .into_iter()
                .filter(|l| !l.ids.is_empty())
                .map(|l| {
                    let count = l.ids.len() as u32;
                    lesson(
                        l.title,
                        l.summary,
                        json!({
                            "melody": { "library": {
                                "ids": l.ids,
                                "shuffle": false,
                                "fit_range": true,
                                // The EarMaster export's tempo is a fixed score
                                // value (often 120), not a practice tempo. The
                                // sight-singing setting must win.
                                "piece_tempo": false
                            }}
                        }),
                    )
                    .of("sight_sing", count)
                })
                .collect();
            (!lessons.is_empty()).then(|| module(m.title, lessons))
        })
        .collect();

    workshop(
        MELODIA,
        "sight_sing",
        1,
        "Melodia",
        "Melodia",
        "The Cole-Lewis Melodia course in the book's own module and lesson order: \
         eleven exercise modules and 381 lessons, one line at a time. \
         Two-part series are sung one part per trial; the app has no simultaneous \
         duet mode yet. No generated or randomly filtered material.",
        modules,
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::courses::level_session;
    use crate::generate::{GenContext, generate_block};
    use crate::library;
    use crate::schema::TrialSpec;
    use crate::validate::validate_session;
    use std::path::Path;

    fn installed_library() -> Vec<library::LibraryPiece> {
        let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../data/library/Melodia");
        let mut pieces = Vec::new();
        let mut paths: Vec<_> = std::fs::read_dir(&dir)
            .unwrap_or_else(|e| panic!("read {}: {e}", dir.display()))
            .map(|e| e.unwrap().path())
            .filter(|p| p.extension().and_then(|x| x.to_str()) == Some("json"))
            .collect();
        paths.sort();
        for path in paths {
            let text = std::fs::read_to_string(&path).unwrap();
            pieces.extend(library::parse_json(&text).unwrap());
        }
        pieces
    }

    fn ids_of(c: &Course) -> Vec<&str> {
        let mut out = Vec::new();
        for level in &c.levels {
            let b = &level.blocks[0];
            let crate::schema::Exercise::SightSing(p) = &b.exercise else {
                panic!("melodia lesson is not sight singing");
            };
            let crate::schema::MelodySource::Library(sel) = &p.melody else {
                panic!("melodia lesson is not library-backed");
            };
            out.extend(sel.ids.iter().map(|v| v.as_str()));
        }
        out
    }

    #[test]
    fn every_id_is_installed_and_used_once() {
        let c = course();
        assert_eq!(c.levels.len(), 381);
        let builtin = crate::courses::builtin_courses()
            .into_iter()
            .find(|x| x.id == MELODIA)
            .expect("Melodia is a built-in course");
        assert_eq!(builtin.category, "Relative pitch");
        assert_eq!(builtin.levels.len(), 381);
        let lib = installed_library();
        let have: std::collections::HashSet<&str> = lib.iter().map(|p| p.id.as_str()).collect();
        let ids = ids_of(&c);
        assert_eq!(ids.len(), 1646);
        let unique: std::collections::HashSet<&str> = ids.iter().copied().collect();
        assert_eq!(unique.len(), ids.len(), "an exercise appears twice");
        for id in unique {
            assert!(have.contains(id), "missing from the library: {id}");
        }
    }

    #[test]
    fn the_sight_singing_tempo_setting_wins_over_the_piece_tempo() {
        let c = course();
        let mut spec = level_session(&c, 1).unwrap();
        let prefs = std::collections::BTreeMap::from([(
            "sight_sing".to_string(),
            serde_json::json!({ "tempo_bpm": 72.0 }),
        )]);
        crate::courses::apply_exercise_prefs(&mut spec, &prefs);

        let mut ctx = GenContext::default();
        ctx.library = installed_library();
        let trials = generate_block(&spec.blocks[0], 7, &ctx).unwrap();
        assert!(!trials.is_empty());
        for t in trials {
            let TrialSpec::Sung(t) = t else {
                panic!("Melodia lesson did not generate a sung trial");
            };
            assert_eq!(
                t.tempo_bpm, 72.0,
                "the sight-singing setting must override the library tempo"
            );
        }
    }

    #[test]
    fn the_first_lesson_sits_in_the_practice_register() {
        let c = course();
        let mut ctx = GenContext::default();
        ctx.library = installed_library();
        let spec = level_session(&c, 1).unwrap();
        let (_floor, target, _ceiling) = library::practice_window(ctx.comfortable);
        for t in generate_block(&spec.blocks[0], 7, &ctx).unwrap() {
            let TrialSpec::Sung(t) = t else {
                panic!("Melodia lesson did not generate a sung trial");
            };
            let score = t.score.expect("sight singing has a score");
            let (lo, hi) = score.range().unwrap();
            let mut midis: Vec<i32> = score.pitched().map(|(_, p)| p.midi()).collect();
            midis.sort_unstable();
            let median = midis[midis.len() / 2];
            assert!(
                lo >= ctx.comfortable.low.0 - 1,
                "low {lo} is far below the comfortable low {}",
                ctx.comfortable.low.0
            );
            assert!(
                hi <= ctx.comfortable.high.0,
                "high {hi} above the comfortable high {}",
                ctx.comfortable.high.0
            );
            assert!(
                median <= target + 7,
                "median {median} is too far above the target {target}"
            );
        }
    }

    #[test]
    fn every_lesson_generates_from_the_installed_library() {
        let c = course();
        let mut ctx = GenContext::default();
        ctx.library = installed_library();
        let mut trials = 0;
        for level in 1..=c.levels.len() as u32 {
            let spec = level_session(&c, level).unwrap();
            let r = validate_session(&spec, &ctx);
            assert!(r.ok, "level {level}: {:?}", r.errors);
            for b in &spec.blocks {
                trials += b.count;
                generate_block(b, 7, &ctx).unwrap_or_else(|e| panic!("level {level}: {}", e.0));
            }
        }
        assert_eq!(trials, 1646);
    }
}
